"""Render AUDIT.json + download_manifest.json into DATA_AUDIT.md (no new analysis)."""
import json, os
H = os.path.dirname(os.path.abspath(__file__)); a = json.load(open(os.path.join(H, "AUDIT.json"))); m = json.load(open(os.path.join(H, "download_manifest.json"))); L = []
L += ["# Data audit (generated by audit.py / audit_report.py from the pinned archives)", "", "## Pinned archives", "| key | record | file | bytes | MD5 | verified |", "|---|---|---|---|---|---|"]
for k, v in m.items(): L.append(f"| {k} | {'10812353 (latest of 8373145)' if k.startswith('streams') else '14625691'} | {'Petersen_etal_Streams_IceCliffs_DataRepo.zip' if k.startswith('streams') else 'Petersen_etal_2025_Kennicott_Glacier_Data.zip'} | {v['size']} | {v['md5']} | {v['status']} (size_ok={v['size_ok']}, md5_ok={v['md5_ok']}) |")
s = a["summary"]; L += ["", "## Kennicott stake backwasting (14625691)", f"{s['csv_files']} CSV files = {s['site_years']} site-years from {len(s['sites'])} named stakes {s['sites']}, years {s['years']}; **{s['observations']} non-blank observations** (309 rows incl. 5 blank rows in 2022 P_IC_S); independent cliffs ≤ {s['independent_cliffs_upper_bound']}. UTC − ADT = 8 h in every row: {s['all_utc_adt_8h']}. D monotone non-decreasing in every series: {s['all_monotone']}. Series with regular daily sampling: {s['regular_daily_series']}.", "", "| year | stake | n obs | first | last | median gap h | max gap h | D first→last cm | slope° | aspect° | median rate cm/day (horizontal) |", "|---|---|---|---|---|---|---|---|---|---|---|"]
for b in a["kennicott_backwasting"]: L.append(f"| {b['year']} | {b['site']} | {b['observations']} | {b['first'][:10]} | {b['last'][:10]} | {b['gap_h_median']:.1f} | {b['gap_h_max']:.0f} | {b['D_first_cm']:g}→{b['D_last_cm']:g} | {b['slope_deg']} | {b['aspect_deg']} | {b['rate_cm_per_day_median']:.1f} |")
L += ["", "Units: D = emerged horizontal stake length, cm (±2 cm, ±1 h per metadata); slope/aspect degrees, one value per site-year. Horizontal rate is not normal melt (see OBSERVATION_OPERATORS.md).", "", "## Stream discharge gauges (10812353)", "| gauge | exp | date | conditions | profiles | mean area m² | surface-float v m/s | floats used | Q m³/s (area × surface float speed) |", "|---|---|---|---|---|---|---|---|---|"]
for g in a["gauges"]:
    if g.get("status") == "ok": L.append(f"| {g['gauge']} | {g['exp']} | {g['date']} | {g['conditions']} | {g['profiles']} | {g['mean_area_m2']:.3f} | {g['float_velocity_m_s_mean']:.2f} ± {g['float_velocity_m_s_sd']:.2f} | {g['floats_used']} | {g['Q_surface_float_m3_s']:.3f} |")
    else: L.append(f"| {g['gauge']} | {g['exp']} | {g['date']} | — | — | — | — | — | **{g['status']}** (listed in gauges_summary.csv) |")
st = a["ice_cliffs_stats"]; L += ["", "Published range 0.06–0.21 m³ s⁻¹ is reproduced (0.061–0.210).", "", "## Ice-cliff inventory and profiles", f"ice_cliffs_stats.csv: {st['rows']} cliffs; columns {st['columns']}; **slope_min > slope_max in {st['fraction_swapped']*100:.0f} % of rows** — {st['note']}. Total planform area {st['planform_area_total_m2']:.3e} m². Ramp profile samples: {a['profiles']['ramp_profile_files']} files {a['profiles']['kinds']}; ArcticDEM cliff profile: {a['profiles']['arcticdem_rows']} points, years {a['profiles']['arcticdem_years']}. Shapefile record counts: {a['dbf_records']}.", "", "## Kennicott archive inventory (files by folder)", json.dumps(a["kennicott_inventory_files_by_folder"]), "", "Not done: no interpolation, no co-location assumption, no conversion of horizontal backwasting to melt."]
open(os.path.join(H, "DATA_AUDIT.md"), "w").write("\n".join(L) + "\n"); print("written")
